<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Order; use App\Models\ShipmentEvent; use App\Services\CourierService; use App\Services\OrderService; use App\Services\SmsService; use Illuminate\Http\Request;
class OrderController extends Controller { public function __construct(private OrderService $orders,private CourierService $courier,private SmsService $sms){} public function index(Request $r){$q=Order::latest();if($r->filled('status'))$q->where('status',$r->status);if($r->filled('q'))$q->where(fn($x)=>$x->where('order_number','like','%'.$r->q.'%')->orWhere('phone','like','%'.$r->q.'%'));return view('admin.orders.index',['orders'=>$q->paginate(25)->withQueryString()]);} public function show(Order $order){$order->load(['items','payments','shipmentEvents']);return view('admin.orders.show',compact('order'));}
public function update(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:pending,confirmed,processing,shipped,delivered,cancelled,returned','payment_status'=>'required|in:unpaid,paid,failed,refunded']);$old=$order->status;$order->update($d);if(in_array($d['status'],['cancelled','returned'])&&!in_array($old,['cancelled','returned']))$this->orders->releaseStock($order);if(!in_array($d['status'],['cancelled','returned'])&&in_array($old,['cancelled','returned'])&&($order->payment_method==='cod'||$order->payment_status==='paid'))$this->orders->commitStock($order);if($old!==$d['status'])$this->sms->send($order->phone,"Order {$order->order_number} status: {$d['status']}.");return back()->with('success','Order updated.');}
public function courier(Order $order){try{$data=$this->courier->createShipment($order);$tracking=$data['tracking_code']??$data['consignment_id']??$data['id']??null;$order->update(['courier_provider'=>config('services.courier.provider'),'courier_tracking_code'=>$tracking,'status'=>'shipped']);ShipmentEvent::create(['order_id'=>$order->id,'provider'=>config('services.courier.provider'),'consignment_id'=>$data['consignment_id']??null,'tracking_code'=>$tracking,'status'=>$data['status']??'created','payload'=>$data]);$this->sms->send($order->phone,"Order {$order->order_number} shipped. Tracking: ".($tracking?:'pending'));return back()->with('success','Courier booking created.');}catch(\Throwable $e){return back()->with('error',$e->getMessage());}}
}
